import type { Media } from "@/lib/media";

type Props = {
  media: Media;
  sizes?: string;
  priority?: boolean;
  className?: string;
  alt?: string;
  style?: React.CSSProperties;
};

/** Responsive <picture> with WebP + JPEG fallbacks generated by the asset pipeline. */
export default function Photo({ media, sizes = "100vw", priority = false, className, alt, style }: Props) {
  const srcset = (ext: string) => media.widths.map((w) => `${media.base}-${w}.${ext} ${w}w`).join(", ");
  return (
    <picture>
      <source type="image/webp" srcSet={srcset("webp")} sizes={sizes} />
      <img
        src={`${media.base}-${media.widths[Math.min(1, media.widths.length - 1)]}.jpg`}
        srcSet={srcset("jpg")}
        sizes={sizes}
        width={media.w}
        height={media.h}
        alt={alt ?? media.alt}
        loading={priority ? "eager" : "lazy"}
        decoding={priority ? "sync" : "async"}
        fetchPriority={priority ? "high" : undefined}
        className={className}
        style={style}
      />
    </picture>
  );
}
